function translate(s){if(lang==='ru')return s;const trimmed=s.trim();if(dict.has(trimmed))return s.replace(trimmed,dict.get(trimmed));
if(trimmed.startsWith('Загрузка отменена. '))return 'Import cancelled. '+translate(trimmed.slice('Загрузка отменена. '.length));
const errorPatterns=[[/^Выберите файл (.+)$/,'Select file $1'],[/^(.+): файл больше 20 МБ$/,'$1: file exceeds 20 MB'],[/^(.+): отсутствует колонка (.+)$/,'$1: missing column $2'],[/^(.+): файл не содержит данных$/,'$1: no data rows'],[/^(.+): больше 100 000 строк$/,'$1: more than 100,000 rows'],[/^(.+) строка (\d+): пустое (.+)$/,'$1 row $2: empty $3'],[/^(.+) строка (\d+): неверная UTC-дата (.+)$/,'$1 row $2: invalid UTC timestamp $3'],[/^Неизвестный статус (.+)$/,'Unknown status $1'],[/^Неверное число колонок в строке (\d+)$/,'Invalid column count in row $1'],[/^Ожидается неотрицательная сумма с точкой и максимум 2 знаками: (.+)$/,'Expected a nonnegative decimal with at most 2 decimal places: $1']];
for(const [re,to] of errorPatterns)if(re.test(trimmed))return trimmed.replace(re,to);
const patterns=[[/^(\d[\d\s\u00a0]*) конверсий$/,'$1 conversions'],[/^(\d+) партнёра$/,'$1 partners'],[/^(\d[\d\s\u00a0]*) записей$/,'$1 records'],[/^(\d[\d\s\u00a0]*) строк в текущем наборе$/,'$1 rows in the current dataset'],[/^(\d+(?:\.\d+)?)% от кликов$/,'$1% of clicks'],[/^(\d+(?:\.\d+)?)% от регистраций$/,'$1% of registrations'],[/^Файл (\w+\.csv)$/,'File $1'],[/^Валюта (\w+) · срез (.+)$/,'Currency $1 · as of $2'],[/^Все снимки по ID, включая будущие\. Срез расчёта: (.+)\.$/,'All snapshots for this ID, including future updates. Calculation cutoff: $1.'],[/^Весь комплект на дату среза: (.+) ID трекера, (.+) ID рекламодателя · (\d+) повторов доставки · (\d+) будущих снимков исключено\. Эти счётчики не зависят от фильтра партнёра и периода\.$/,'Full dataset at cutoff: $1 tracker IDs, $2 advertiser IDs · $3 delivery retries · $4 future snapshots excluded. These counts are independent of partner and date filters.']];
for(const [re,to] of patterns){const widened=new RegExp(re.source.replaceAll('\\d\\s','\\d,\\s'),re.flags);if(widened.test(trimmed))return trimmed.replace(widened,to);}
// Reason options append a numeric count to the translated flag label.
const match=trimmed.match(/^(.*) (\(\d+\))$/);if(match&&dict.has(match[1]))return dict.get(match[1])+' '+match[2];return s;}
function apply(root=document){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(n.parentElement?.closest('script,style,pre,code,.language-switch'))continue;const old=cache.get(n),original=old&&old.rendered===n.nodeValue?old.original:n.nodeValue;const rendered=translate(original);if(n.nodeValue!==rendered)n.nodeValue=rendered;cache.set(n,{original,rendered});}
for(const el of root.querySelectorAll('[placeholder],[aria-label]')){if(el.closest('.language-switch'))continue;let a=attrs.get(el)||{};for(const name of ['placeholder','aria-label']){const val=el.getAttribute(name);if(val===null)continue;const old=a[name],original=old&&old.rendered===val?old.original:val;const rendered=translate(original);el.setAttribute(name,rendered);a[name]={original,rendered};}attrs.set(el,a);}
document.documentElement.lang=lang;document.querySelectorAll('[data-language]').forEach(b=>{const active=b.dataset.language===lang;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});}
window.I18N={apply,translate,get language(){return lang;},get locale(){return lang==='en'?'en-GB':'ru-RU';},setLanguage(value){lang=value==='ru'?'ru':'en';try{localStorage.setItem('ledger-language',lang);}catch{}apply();}};
